set -e
mkdir -p /mnt/data/rest_department_pack/src/departments/shared
mkdir -p /mnt/data/rest_department_pack/src/departments/{ECE,Mechanical,Civil,Humanities,DMS,DCA}
cat > /mnt/data/rest_department_pack/src/departments/shared/restDepartments.js <<'EOF'
export const restDepartments = {
  ECE:{id:'ece',name:'Electronics and Communication Engineering',overview:`This department was established during the inception of the institute in 2007 as the Department of Electronics and Communication Engineering (ECE). The Department was set up to nourish the students into highly skilled engineers with extensive knowledge in the field of Electronics & Communication. The department is well equipped with all the gadgets, instruments and softwares required for experimental work. Project work throughout the course strengthens the necessity for a combination of practical and theoretical skills and abilities. The students are also encouraged to participate in extracurricular activities and clubs.\n\nApart from the core electronics laboratories, the electronics industry has tied hands with the recent ongoing fields such as Artificial Intelligence & Machine Learning, Blockchain, Cyber Security, Data Science, Internet of Things (IOT), Robotics etc. And to prepare the students for the technological advancements the department offers subjects like Digital Image Processing, Cyber Security, Mobile Communication Networks, Soft Computing etc.`,hod:{name:'Prof. (Dr.) Parmod Singh',designation:'HOD, ECE',message:`Electronics & Communication Engineering continues to be a growing industry as indicated by the current demand for Graduates. The Electronics & Communication Department was set up with the aim of nourishing the students into highly skilled engineers possessing extensive knowledge in the field of Electronics & Communication.\n\nWe aid to prepare students for careers as professional engineers through an education in fundamental principles presented in the context of real application and design.`},vision:'To become a leading centre of excellence in Electronics and Communication Engineering, fostering innovation, research, and leadership in the field, while continually exploring self, society, and nature through reflective and conscious learning.',mission:['To cultivate a culture of inspiration and innovation in Electronics and Communication Engineering through hands-on, experimental teaching and learning, leading to the advancement of knowledge and technology.','To encourage students to be self-motivated and constantly improve their skills in electronics, communication, and related fields, fostering creativity, innovation, and leadership.','To develop students into responsible engineers who are committed to personal and social integrity, engaged in lifelong learning and reflective practice, and contributing to shared human values.'],peo:[],pso:[],labs:['Basic Electrical Engineering Lab — ESC107','Workshop-I — ESC 104','Electronics Devices Lab — EC351','Digital System Design Lab — EC352','Network Theory Lab — EC353','Electronics Project Workshop-I — ES303','Analog and Digital Communication Lab — EC451','Analog Circuits Lab — EC452','Microprocessors & Microcontrollers Lab — ECC51','Electronics Project Workshop-II — ES402','Digital Signal Processing Lab — ECC53','Electromagnetic Waves Lab — ECC52','Electronics Project Workshop-III — ES555','Computer Networks Lab — EC652','Electronics Measurement Lab — EC653','Digital Image Processing Lab — ECEL655B','Electronics Project Workshop-IV — ES654','Major Project — ECP701','Electronics Workshop-V — ES751'],faculty:[['Rajiv Kumar Anand','Professor','Ph.D'],['Arvind Kumar Pandey','Professor','Ph.D'],['Ravinder Kumar','Professor','Ph.D'],['Mukesh Kumar','Professor','Ph.D'],['Pramod Singh','Professor','Ph.D'],['Romisha','Assistant Professor','M.Tech'],['Kundan Agrawal','Assistant Professor','M.Tech'],['Mahaveer Prashad Sharma','Assistant Professor','B.E'],['Neeraj Joshi','Assistant Professor','M.Tech'],['Pooja Sharma','Assistant Professor','M.Tech'],['Shashee Lata Rajput','Assistant Professor','M.Tech'],['Kumail Hasan Naqvi','Assistant Professor','M.Tech'],['Jitendra Ahirwar','Assistant Professor','M.Tech'],['Vikalendu','Assistant Professor','M.Tech'],['Vishakha Yadav','Assistant Professor','M.Tech'],['Mittar Pal','Assistant Professor','M.Tech'],['Isha Gautam','Assistant Professor','M.Tech'],['Bikrant Kumar','Assistant Professor','M.Tech']]},
  Mechanical:{id:'mechanical',name:'Mechanical Engineering',overview:`Mechanical Engineering Department is the driving force behind many of our technological and industrial processes. The Department is rightly recognized as the mother of engineering. Mechanical engineers require a solid understanding of key concepts including mechanics, kinematics, thermodynamics, energy, and manufacturing. The benefit of this fundamental role is that the subject provides a wide choice of career opportunities in industries as diverse as food, pharmaceuticals, energy, petrochemical industries, and environmental protection and conservation. It is one of the oldest and broadest engineering disciplines. The department has well-qualified faculty who produce numerous publications in International/National journals, highlighting the emphasis on research and development. The Department has a modern workshop equipped with the latest machinery in fitting and machine shops.\n\nMechanical Engineering is concerned with all types of machinery in industries and all aspects of their mechanism and functioning- the design, development, construction, production, installation, operation, and maintenance.`,hod:{name:'Dr. Sindhu Kumar',designation:'HOD, Mechanical Engineering',message:'Our mission is to enhance knowledge, foster critical thinking, and champion the implementation of Project-Based Learning (PBL) to prepare students for the dynamic needs of society. We strive to make our students not only skilled and competent but also equipped to contribute meaningfully to the ever-evolving world.'},vision:'To cultivate mechanical engineers who embody technical excellence, innovative leadership, and ethical consciousness, contributing to sustainable technological advancements while being inspired by self-reflection, societal needs, and environmental harmony.',mission:['To foster a culture of experiential and applied learning, enabling students to develop advanced technical skills, creativity, and problem-solving abilities in mechanical engineering.','To inspire students to pursue innovative research and sustainable engineering solutions while nurturing leadership and entrepreneurial potential.','To instill ethical values and a sense of responsibility, encouraging students to engage in self-reflective practices, contribute to societal well-being, and uphold the principles of environmental stewardship.'],peo:['Graduates will establish themselves as competent mechanical engineering professionals by applying engineering knowledge and problem-solving skills in industry, research, or related fields.','Graduates will adapt to evolving industrial practices by upgrading their technical competencies and assuming roles of increased responsibility in engineering or allied sectors.','Graduates will demonstrate ethical conduct, teamwork, and social responsibility while contributing effectively to organizational and societal development.'],pso:['Apply mechanical engineering principles, analytical methods, and modern tools to solve complex engineering problems across core and allied domains.','Develop and optimize mechanical systems, processes, and components by integrating design, manufacturing, and energy considerations.'],labs:['Material Science Lab','Strength of materials Lab','Fluid Mechanics and Machines Lab','Dynamics of Machine Lab','Production Technology Lab & AMT Lab','Internal Combustion Engine Lab','Heat Transfer Lab','Refrigeration & Air Conditioning Lab','Computer Aided Design lab'],faculty:[['Sindhu Kumar','Professor','Ph.D'],['Ashish Kumar Thakur','Professor','Ph.D'],['Jaivir Singh','Associate Professor','Ph.D'],['Dhirendra Pratap Singh','Associate Professor','Ph.D'],['Anshuman Agarwal','Assistant Professor','M.Tech'],['Niranjan Kumar','Assistant Professor','M.Tech'],['Prathvi Singh','Assistant Professor','M.Tech'],['Ravinder Singh','Assistant Professor','M.Tech'],['Rone','Assistant Professor','M.Tech'],['Sunder Sharma','Assistant Professor','M.Tech'],['Vivek Madhav Roy','Assistant Professor','M.Tech'],['Manoj','Assistant Professor','M.Tech'],['Mohd Irfan Khan','Assistant Professor','M.Tech'],['Manish Kumar','Assistant Professor','M.Tech'],['Chander Pal','Assistant Professor','M.Tech'],['Naveen Kumar','Assistant Professor','M.Tech']]},
  Civil:{id:'civil',name:'Civil Engineering',overview:`One of the primary engineering departments of the Echelon Institute of Technology, the Department of Civil Engineering actively promotes curriculum development activity by updating existing courses, developing new courses and preparing resource material for teaching. The Department has a number of ongoing research projects. It organizes seminars/symposia for professional interaction. The Department contributes to the interdisciplinary academic and research activity of the Institute.\n\nCourses offered by the civil engineering department are aligned with the requirements of the industry. Students work on real-life projects with advanced teaching aids and research facilities. Faculty members hold Bachelor’s, Master’s, and Ph.D. degrees, from NITs and IITs, with research publications in reputed journals and conferences. Software labs such as AutoCAD and STAAD Pro are functional. Industrial visits and GATE classes are also provided.`,hod:{name:'Dr. Sindhu Kumar',designation:'HoD, Civil Engineering',message:'Our mission is to enhance knowledge, foster critical thinking, and champion the implementation of Project-Based Learning (PBL) to prepare students for the dynamic needs of society. We strive to make our students not only skilled and competent but also equipped to contribute meaningfully to the ever-evolving world.'},vision:'To cultivate civil engineering technocrats, committed to pioneering innovations at the intersection of technology, nature, and society. The department will inspire and empower students through continuous self-exploration, fostering an environment that promotes creativity, exploration, and sustainable growth in building infrastructure that shapes the future.',mission:['To foster a culture of inspiration and innovation in civil engineering through effective, experiential learning, enabling students to develop expertise and wisdom that drives technological breakthroughs and sustainable solutions.','To inspire self-driven students in their pursuit of continuous development in computational, creative, and leadership skills, preparing them to address global challenges and contribute to societal well-being through engineering solutions.','To instill self-reflective consciousness in students, emphasizing personal, social, and environmental integrity, and encouraging deep inquiry and collaboration that cultivates shared human values and consciousness in the field of civil engineering.'],peo:['To make graduates of the Civil Engineering program capable of contributing towards Nation’s development by providing sustainable solutions to a wide range of diverse and complicated Civil Engineering problems in different application sectors including physical infrastructure.','To transform graduates of the Civil Engineering program into successful professionals in designing and executing national standard products and services in the field of Civil Engineering, becoming entrepreneurs, and pursuing further education and research.','To enable graduates of the Civil Engineering Program for adapting to dynamic changes in the technological scenarios and handle broader social challenges with a rational and flexible decision-making style.'],pso:['Capability to manage large infrastructure projects ensuring safe and cost-effective execution of projects having knowledge of fast track construction and project management.','Ability to use building software packages to calculate safe loads and stresses for designing structural members to ensure safety and serviceability.','Ability to provide innovative solutions for traffic safety and efficiency through intelligent transportation systems, and mitigate the environmental impact of construction by adopting green building concepts.'],labs:['Surveying Lab','Soil Mechanics Lab / Geotechnical Lab','Environmental Engineering Laboratory'],faculty:[['Bhartesh','Associate Professor','Ph.D'],['Rambha','Associate Professor','Ph.D'],['Shivam Aggarwal','Associate Professor','Ph.D'],['Abhishek Kumar Singh','Assistant Professor','M.Tech'],['Naveen Kaushik','Assistant Professor','M.Tech'],['Rohit Shukla','Assistant Professor','M.Tech'],['Ramu Kumar Yadav','Assistant Professor','M.Tech'],['Saurav Raj','Assistant Professor','M.Tech'],['Vivek Sharma','Assistant Professor','M.Tech']]},
  Humanities:{id:'humanities',name:'Humanities and Applied Science Department',overview:`Our department is dedicated to equipping bright minds with the knowledge and tools to shape the future as accomplished engineers. We are committed to molding students into globally competent professionals with well-rounded personalities, prepared to excel in their chosen fields.\n\nWith a team of highly qualified and experienced faculty, state-of-the-art laboratories, smart classrooms, and hands-on workshops, we offer an exceptional learning environment. Our teaching methodologies are designed not only to impart technical expertise, but also to nurture scientific temperament, creative thinking, and strong analytical skills.\n\nWe empower our students to embrace future technologies with confidence, curiosity, and a commitment to becoming innovative leaders and responsible global citizens.`,hod:{name:'Dr. Anupama Jain',designation:'HoD, HAS',message:'The Department of Humanities and Applied Sciences forms the foundation of engineering education with its four distinct wings: Physics, Chemistry, Mathematics, and English. Equipped with state-of-the-art laboratories in Physics, Chemistry, and English, the department offers an ideal learning environment to empower young minds and prepare them to become future engineers.'},vision:'The department of Applied Sciences & Humanities is committed to inculcate competence and proficiency in the students in the field of basic sciences, technology and personality development so that they can think critically & logically, communicate clearly, and live ethically. The department is also dedicated to provide fundamental education through promoting research in diverse and interdisciplinary field.',mission:['To develop a strong scientific foundation through fundamental principles of physics, chemistry and mathematics to pursue a successful engineering carrier and to train the students to apply these basic principles in real world situation.','To inculcate extraordinary analytical, logical, soft skill and ethical values in students to make them ready for corporate world.','To integrate human values and social concerns with technical education.','To promote and strengthen R & D programs with other technical institutions in India.'],peo:[],pso:[],labs:['Engineering Physics Lab','Engineering Chemistry Lab','Language Lab','Mathematics Lab'],faculty:[['Anupama Jain','Professor','Ph.D'],['Md. Faiyazur Rahman Faizi','Professor','Ph.D'],['Kailash Narayan','Professor','Ph.D'],['Shital Prasad','Professor','Ph.D'],['Pankaj Srivastva','Professor','Ph.D'],['Sunil Verma','Professor','Ph.D'],['Vandana Agrawal','Professor','Ph.D'],['Harish Srivastava','Professor','Ph.D'],['Poonam Rani','Associate Professor','Ph.D'],['Arti Kadam','Assistant Professor','M.Sc'],['Karishma Hanotiya','Assistant Professor','M.Sc'],['Meenu','Assistant Professor','M.Sc'],['Moulima Das','Assistant Professor','M.A'],['Naveen Kumar','Assistant Professor','M.A'],['Sagardeep Thakuria','Assistant Professor','M.A'],['Saif Abbas','Assistant Professor','M.Sc'],['Alka','Assistant Professor','M.Sc'],['Shiva Verma','Assistant Professor','M.Sc'],['Shweta Singh','Assistant Professor','M.Sc'],['Vikas Kumar','Assistant Professor','M.Sc'],['Shaswita','Assistant Professor','M.Sc'],['Muskaan Kapur','Assistant Professor','M.A'],['Bharti Yadav','Assistant Professor','Ph.D'],['Radha','Assistant Professor','M.A'],['Pushplata','Assistant Professor','M.Sc'],['Amita','Assistant Professor','M.Sc'],['Harsh Saxena','Assistant Professor','M.Sc'],['Faizan Ul Haque','Assistant Professor','M.Sc'],['Pinki Devi','Assistant Professor','M.Sc'],['Sakshi Gandhi','Assistant Professor','Ph.D'],['Brijesh Sahani','Assistant Professor','M.Sc, M.Tech']]},
  DMS:{id:'management',name:'Department of Management Studies',overview:`The Department of Management Studies (DMS) is committed to fostering an entrepreneurial culture and nurturing innovative minds with managerial skills that are socially and globally relevant. Anchored in its vision, the department strives to produce competent professionals equipped to address contemporary challenges and contribute meaningfully to society.\n\nDMS emphasizes imparting advanced management concepts and skill-based training through an application-oriented pedagogy. The curriculum is carefully designed to blend theoretical knowledge with practical insights, enabling students to develop critical thinking, problem-solving, and leadership capabilities. By incorporating real-world case studies, projects, and cutting-edge technologies, the department ensures that students are prepared to meet the demands of the ever-evolving business landscape.`,hod:{name:'Dr. Irfanullah Khan',designation:'HOD, DMS',message:'Our department is committed to delivering a world-class education in business management, nurturing the leaders and innovators of tomorrow. We provide students with a dynamic and engaging learning environment that blends theoretical knowledge with practical insights, preparing them for successful careers in a wide range of industries.'},vision:'To develop visionary leaders who drive sustainable business and societal progress fostering a culture of inspiration, exploration, and growth to inspire transformative change for organizations and communities.',mission:['To foster innovation and experiential learning by equipping students with evolving knowledge of business management principles and practices.','To develop self-inspired leaders with strategic thinking, creativity, and ethical consciousness to address complex business challenges.','To instill refl ective and collaborative values, enabling students to contribute meaningfully to organizational and societal integrity.'],peo:[],pso:[],labs:[],faculty:[['Dr. Sima Kumari','Professor & Dean',''],['Dr. Irfanullah Khan','Professor & HoD',''],['Dr. Bajrang Lal','Associate Professor',''],['Dr. Priyanka Sisodia','Associate Professor',''],['Dr. Neha Mittal','Associate Professor',''],['Ms. Priyanka','Assistant Professor/Admission',''],['Mr. Abhishek','Assistant Professor',''],['Mr. Ajeet Yadav','Assistant Professor',''],['Mr. Deepesh Agrawal','Assistant Professor',''],['Mr. Ekansh Thapliyal','Assistant Professor',''],['Mr. Gireesh Mangal','Assistant Professor',''],['Mr. Girish Devendiran','Assistant Professor',''],['Mr. Mohit Kapil','Assistant Professor',''],['Mr. Raman Gupta','Assistant Professor',''],['Mr. Shalabh Saxena','Assistant Professor',''],['Ms. Abhilasha Singh','Assistant Professor',''],['Ms. Anjali Kukreti','Assistant Professor',''],['Ms. Anjali Negi','Assistant Professor',''],['Ms. Bhumika Maan','Assistant Professor',''],['Ms. Nisha','Assistant Professor',''],['Ms. Pinky Sharma','Assistant Professor',''],['Ms. Preeti Arora','Assistant Professor',''],['Ms. Rakshita Verma','Assistant Professor',''],['Ms. Richa Saini','Assistant Professor',''],['Ms. Ruby Jain','Assistant Professor',''],['Ms. Saroj','Assistant Professor',''],['Ms. Sonam','Assistant Professor',''],['Ms. Vinita Singh','Assistant Professor','']]},
  DCA:{id:'computer-applications',name:'Department of Computer Applications',overview:`We have excelled in every initiative that we undertook and we have stood together in facing the challenges in providing quality education to students. Department of Computer Applications contains faculty members which are a mix of industrial and academic expertise.\n\nThe Department of Computer Applications is not only active in research but also in encouraging students for curricular and extracurricular activities. The department prepares students for a broad range of careers in Government sector, software industries, Entrepreneurship by hands on trainings, projects, skill development programs, ethics education for management. Department of Computer Applications is a hub of activity with students having the opportunity to truly engage themselves in active learning through effective participation in Workshops, Seminars, Certification Programs, Tech-Fest, Innovative R&D Programs and Industrial visits.`,hod:{name:'Ms. Shallu Hassija',designation:'HOD, DCA',message:'The Department of Computer Applications of the Echelon Institute of Technology offers BCA and MCA courses under the banner of JCBUST, Faridabad (YMCA). We endeavour to impart the curriculum for each of the courses to nurture our students into market-ready trained manpower through well designed curriculum inculcated with the right blend of Seminars, Technical quizzes, Project displays, Paper presentations, Industrial Visits etc.'},vision:'To develop innovative technical leaders at the forefront of technological advancements. Committed to lifelong learning and self-reflection, the department fosters creativity, growth, and transformative solutions to shape the future of technology and its societal impact.',mission:['To cultivate a culture of innovation, exploration, and experiential learning in computer applications, fostering the growth of knowledge, skills, and wisdom.','To inspire students to continuously enhance their computational, creative, and leadership abilities, driving them toward excellence and innovation.','To nurture self-reflective professionals who uphold personal and societal integrity, engage in meaningful inquiry, and contribute to shared human values through technology and collaboration.'],peo:['Demonstrate analytical and design skills including the ability to generate creative solutions and foster team-oriented professionalism through effective communication in their careers.','Graduates would expertise in successful careers based on their understanding of formal and practical methods of application development using the concept of computer programming languages and design principles in national and international level.'],pso:[],labs:['C Programming Lab — BCA-23-111','Digital Electronics Lab — BCA-23-113','Workshop I (Hardware) — BCA-23-115','OS Lab — BCA-23-108','Digital Electronics Lab II — BCA-23-110','Workshop II (Networking) — BCA-23-112','Data Structures Lab — BCA-23-209','Object-oriented Programming Using C++ Lab — BCA-23-211','Internet and Web Technology Lab — BCA-23-213','Java Lab — BCA-17-305','VB.NET — BCA-17-305','Big Data I — BCA-DS-305','Machine Learning I — BCA-DS-306','Machine Learning II — BCA-DS-316','Big Data II — BCA-DS-315','DBMS Lab — MCA-20-113','OOPS Lab — MCA-20-115','Operating System Lab — MCA-20-117','Data Structure lab using C/C++ — MCA-20-111','ADA Lab — MCA-20-112','AIML Lab — MCA-20-114','Software Enginering Lab — MCA-20-116','Java Lab — MCA-20-118','Hadoop LAB — MCA-20-211','Dot Net programming using C# and / or VB. Net — MCA-20-213','Soft Computing Lab — MCA-20-215','Minor Project — MCA-20-217','Major Project — MCA-20-202'],faculty:[['Ms. Shalu Hassija','Assistant Professor & HoD',''],['Dr. Azmat Ali Khan','Professor',''],['Ms. Abhilasha Vimal Singh','Associate Professor',''],['Mr. Amarjeet Singh','Associate Professor',''],['Mr. Deepak Kumar Sharma','Associate Professor',''],['Mr. Jawed','Associate Professor',''],['Ms. Mahima Magon','Associate Professor',''],['Dr. Nirmal Kaur','Associate Professor',''],['Mr. Ravinder Singh Madhan','Associate Professor',''],['Ms. Kavita','Assistant Professor',''],['Mr. Mahender Singh','Assistant Professor',''],['Ms. Mansi Gupta','Assistant Professor',''],['Mr. Mohammad Aamir','Assistant Professor',''],['Ms. Payal','Assistant Professor',''],['Ms. Pragati','Assistant Professor',''],['Mr. Rahul Kumar','Assistant Professor',''],['Mr. Rajeev Sharma','Assistant Professor',''],['Mr. Ranjeet Kumar Roy','Assistant Professor',''],['Mr. Raza Mehdi','Assistant Professor',''],['Mr. Rohit Kumar','Assistant Professor',''],['Mr. Sandeep Kumar','Assistant Professor',''],['Mr. Saransh Prakash','Assistant Professor',''],['Ms. Savita','Assistant Professor',''],['Ms. Shabih Zehra','Assistant Professor',''],['Mr. Sujeet Kumar','Assistant Professor',''],['Ms. Sunita','Assistant Professor',''],['Mr. Surendra Kumar Goyal','Assistant Professor','']]}
};
