cat > /mnt/data/rest_department_pack/src/departments/shared/DepartmentPage.jsx <<'EOF'
import {useEffect,useState} from 'react';import {Link} from 'react-router-dom';import Navbar from '../../components/Navbar/Navbar';import Sidebar from '../../components/Sidebar/Sidebar';import Hero from '../../components/Hero/Hero';import './DepartmentPage.css';
const tabs=['Department Overview',"HOD's Message",'Vision and Mission','PEO, PO & PSOs','Faculty','Department Laboratories','Departmental Newsletter'];
export default function DepartmentPage({department}){const[visible,setVisible]=useState(false);useEffect(()=>{const f=()=>setVisible(scrollY>innerHeight*.55);addEventListener('scroll',f);f();return()=>removeEventListener('scroll',f)},[]);return <div className={visible?'rest-dept sidebar-visible':'rest-dept'}><Navbar/><Sidebar tabs={tabs} visible={visible}/><main className="rest-main"><Hero title={department.name} video="/videos/department-bg.mp4"/><section id="section-0" className="rest-section"><b>01 / OVERVIEW</b><span>THE DEPARTMENT</span><h2>Engineering with <i>purpose.</i></h2>{department.overview.split('\n\n').map((x,i)=><p key={i}>{x}</p>)}</section><section id="section-1" className="rest-section rest-dark"><b>02 / HOD'S MESSAGE</b><span>LEADERSHIP</span><div className="rest-two"><h2>{department.hod.name}<small>{department.hod.designation}</small></h2><div>{department.hod.message.split('\n\n').map((x,i)=><p key={i}>{x}</p>)}</div></div></section><section id="section-2" className="rest-section"><b>03 / VISION & MISSION</b><span>DIRECTION</span><h2>Built for the <i>future.</i></h2><div className="rest-grid"><article><strong>VISION</strong><p>{department.vision}</p></article><article><strong>MISSION</strong><ol>{department.mission.map((x,i)=><li key={i}>{x}</li>)}</ol></article></div></section><section id="section-3" className="rest-section rest-dark"><b>04 / PEO, PO & PSOs</b><span>OUTCOMES</span><div className="rest-grid">{department.peo.length>0&&<article><strong>PEOs</strong>{department.peo.map((x,i)=><p key={i}><b>PEO {i+1}</b>{x}</p>)}</article>}{department.pso.length>0&&<article><strong>PSOs</strong>{department.pso.map((x,i)=><p key={i}><b>PSO {i+1}</b>{x}</p>)}</article>}{!department.peo.length&&!department.pso.length&&<p>The current department source does not expose PEO/PSO text here, so none has been invented.</p>}</div></section><section id="section-4" className="rest-section rest-link"><b>05 / FACULTY</b><span>ACADEMIC COMMUNITY</span><h2>Minds that <i>shape minds.</i></h2><p>Explore the current faculty directory published by EIT.</p><Link to={`/${department.id}/faculty`}>EXPLORE FACULTY DIRECTORY ↗</Link></section><section id="section-5" className="rest-section"><b>06 / LABORATORIES</b><span>PRACTICAL LEARNING</span><h2>Where theory <i>gets tested.</i></h2><div className="rest-labs">{department.labs.map((x,i)=><article key={i}><small>{String(i+1).padStart(2,'0')}</small><h3>{x}</h3></article>)}</div></section><section id="section-6" className="rest-section rest-dark"><b>07 / NEWSLETTER</b><span>DEPARTMENTAL PUBLICATIONS</span><h2>Stay <i>informed.</i></h2><a href="https://www.eitfaridabad.com/newsletters.php" target="_blank" rel="noreferrer">OPEN NEWSLETTER ARCHIVE ↗</a></section></main></div>}
EOF
cat > /mnt/data/rest_department_pack/src/departments/shared/FacultyDirectory.jsx <<'EOF'
import{useState}from'react';import{Link}from'react-router-dom';import Navbar from'../../components/Navbar/Navbar';import'./DepartmentPage.css';
export default function FacultyDirectory({department}){const[q,setQ]=useState('');const f=department.faculty.filter(x=>x.join(' ').toLowerCase().includes(q.toLowerCase()));return <div className="faculty-rest"><Navbar/><main className="faculty-rest-main"><section className="faculty-rest-hero"><span>{department.name}</span><h1>Our<br/><i>Faculty</i></h1></section><section className="faculty-rest-list"><div className="faculty-rest-top"><div><span>ACADEMIC COMMUNITY</span><h2>Faculty Directory</h2></div><input placeholder="Search faculty..." value={q} onChange={e=>setQ(e.target.value)}/></div><div className="faculty-rest-grid">{f.map((x,i)=><article key={i}><small>{String(i+1).padStart(2,'0')}</small><div><h3>{x[0]}</h3><span>{x[1]}</span>{x[2]&&<em>{x[2]}</em>}</div><b>↗</b></article>)}</div><Link to={`/${department.id}`}>← Back to department</Link></section></main></div>}
EOF
cat > /mnt/data/rest_department_pack/src/departments/shared/DepartmentPage.css <<'EOF'
.rest-dept,.faculty-rest{background:#eee8d9;color:#12382f;min-height:100vh}.rest-main,.faculty-rest-main{padding-top:82px}.rest-section{padding:115px 8vw}.rest-section>span,.faculty-rest-hero>span,.faculty-rest-top>div>span{display:block;color:#9b7a38;font-size:11px;letter-spacing:.24em;text-transform:uppercase;margin:15px 0 25px}.rest-section>b{font-size:11px;letter-spacing:.2em;color:#9b7a38}.rest-section h2{font:400 clamp(48px,6vw,90px)/.95 Georgia,serif;margin:0 0 45px}.rest-section h2 i,.faculty-rest-hero h1 i{font-style:italic}.rest-section p,.rest-section li{max-width:900px;font-size:17px;line-height:1.8}.rest-dark{background:#12382f;color:#eee8d9}.rest-two,.rest-grid{display:grid;grid-template-columns:1fr 1fr;gap:50px}.rest-two h2 small{display:block;font:normal 12px Arial;letter-spacing:.15em;color:#9b7a38;margin-top:20px}.rest-grid{gap:1px;background:rgba(18,56,47,.2)}.rest-grid article{background:#eee8d9;padding:40px}.rest-dark .rest-grid article{background:#12382f}.rest-grid strong{font-size:11px;letter-spacing:.2em;color:#9b7a38}.rest-grid li{margin:15px 0}.rest-grid p b{display:block;color:#9b7a38;font-size:11px}.rest-link{background:#e2dac7}.rest-section a{display:inline-block;color:inherit;text-decoration:none;border:1px solid currentColor;padding:16px 22px;font-size:11px;letter-spacing:.16em;margin-top:20px}.rest-labs{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:rgba(18,56,47,.2)}.rest-labs article{background:#eee8d9;min-height:160px;padding:30px}.rest-labs small{color:#9b7a38}.rest-labs h3{font:400 25px Georgia,serif;margin-top:40px}.faculty-rest-hero{min-height:58vh;background:linear-gradient(135deg,#12382f,#1c493d,#0d2923);color:#eee8d9;padding:80px 8vw;display:flex;flex-direction:column;justify-content:flex-end}.faculty-rest-hero h1{font:400 clamp(70px,9vw,150px)/.85 Georgia,serif;margin:0}.faculty-rest-list{padding:110px 8vw}.faculty-rest-top{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:60px}.faculty-rest-top h2{font:400 clamp(45px,5vw,80px) Georgia,serif;margin:15px 0 0}.faculty-rest-top input{width:280px;padding:15px 0;border:0;border-bottom:1px solid #12382f;background:transparent;outline:0}.faculty-rest-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1px;background:rgba(18,56,47,.2)}.faculty-rest-grid article{background:#eee8d9;min-height:180px;padding:30px;display:flex;justify-content:space-between}.faculty-rest-grid small{color:#9b7a38}.faculty-rest-grid h3{font:400 27px Georgia,serif;margin:35px 0 8px}.faculty-rest-grid span{display:block;font-size:12px;text-transform:uppercase;letter-spacing:.08em}.faculty-rest-grid em{display:block;font-size:12px;opacity:.55;margin-top:8px;font-style:normal}@media(max-width:768px){.rest-section{padding:75px 7vw}.rest-two,.rest-grid,.faculty-rest-grid{grid-template-columns:1fr}.rest-labs{grid-template-columns:1fr}.faculty-rest-top{flex-direction:column;align-items:flex-start;gap:30px}.faculty-rest-top input{width:100%}.faculty-rest-list{padding:70px 7vw}}
EOF
